//! L5 tests (TEST §2): the mpv core, headless (`vo=null`, `ao=null`), on the media
//! generated by `cargo xtask fixtures`. They are ignored by default and run with
//! `cargo xtask ci --full`.

// Test helpers may panic on setup failures.
#![allow(clippy::expect_used, clippy::unwrap_used)]

use std::path::PathBuf;
use std::sync::mpsc::{Receiver, channel};
use std::time::{Duration, Instant};

use nikomiru_player::control::{LoadToken, Stamped};
use nikomiru_player::options::FIXED;
use nikomiru_player::player::{EndFile, instances_created};
use nikomiru_player::{LoadRequest, Player, PlayerEvent, PlayerHandle, VideoOutput};

const NEEDS: &str = "L5: needs libmpv and `cargo xtask fixtures`";

fn fixture(name: &str) -> String {
    let dir = std::env::var_os("NIKOMIRU_FIXTURES").map_or_else(
        || PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../target/fixtures"),
        PathBuf::from,
    );
    let path = dir.join(name);
    assert!(
        path.exists(),
        "missing fixture {}: run `cargo xtask fixtures`",
        path.display()
    );
    path.to_string_lossy().into_owned()
}

struct Harness {
    _player: Player,
    h: PlayerHandle,
    rx: Receiver<Stamped<PlayerEvent>>,
    token: LoadToken,
}

impl Harness {
    fn new() -> Self {
        let (tx, rx) = channel();
        let player = Player::new(VideoOutput::Null, move |e| {
            let _ = tx.send(e);
        })
        .expect("mpv");
        let h = player.handle();
        Self {
            _player: player,
            h,
            rx,
            token: LoadToken::default(),
        }
    }

    fn load(&mut self, name: &str, request: LoadRequest) {
        let (token, errors) = self.h.load(&fixture(name), request).expect("load");
        assert!(errors.is_empty(), "{errors:?}");
        self.token = token;
    }

    /// Events of the current load until `pred` matches or the timeout expires.
    fn wait(
        &self,
        timeout: Duration,
        mut pred: impl FnMut(&PlayerEvent) -> bool,
    ) -> Vec<PlayerEvent> {
        let deadline = Instant::now() + timeout;
        let mut seen = Vec::new();
        while let Some(left) = deadline.checked_duration_since(Instant::now()) {
            let Ok(ev) = self.rx.recv_timeout(left) else {
                break;
            };
            if let Some(ev) = ev.current(self.token) {
                let done = pred(&ev);
                seen.push(ev);
                if done {
                    break;
                }
            }
        }
        seen
    }

    fn loaded(&self) {
        let seen = self.wait(Duration::from_secs(10), |e| *e == PlayerEvent::FileLoaded);
        assert_eq!(seen.last(), Some(&PlayerEvent::FileLoaded), "{seen:?}");
    }

    fn prop(&self, name: &str) -> String {
        self.h.property_string(name).unwrap_or_default()
    }

    fn time_pos(&self) -> f64 {
        self.prop("time-pos").parse().unwrap_or(-1.0)
    }

    /// Waits until a property reaches a value.
    fn until(&self, name: &str, ok: impl Fn(&str) -> bool) -> String {
        let deadline = Instant::now() + Duration::from_secs(5);
        loop {
            let v = self.prop(name);
            if ok(&v) || Instant::now() > deadline {
                return v;
            }
            std::thread::sleep(Duration::from_millis(20));
        }
    }
}

// T-ARC-001
#[test]
#[ignore = "L5: needs libmpv and `cargo xtask fixtures`"]
fn events_for_every_observed_property() {
    let _ = NEEDS;
    let mut t = Harness::new();
    t.load("av_basic.mkv", LoadRequest::default());
    let seen = t.wait(Duration::from_secs(3), |_| false);
    let has = |f: fn(&PlayerEvent) -> bool| seen.iter().any(f);
    assert!(has(|e| *e == PlayerEvent::FileLoaded));
    assert!(has(|e| matches!(e, PlayerEvent::TimePos(_))));
    assert!(has(|e| matches!(e, PlayerEvent::Duration(_))));
    assert!(has(|e| matches!(e, PlayerEvent::Pause(_))));
    assert!(has(|e| matches!(e, PlayerEvent::Speed(_))));
    assert!(has(|e| matches!(e, PlayerEvent::Volume(_))));
    assert!(has(|e| matches!(e, PlayerEvent::Mute(_))));
    assert!(has(|e| matches!(e, PlayerEvent::Tracks(_))));
    assert!(has(|e| matches!(e, PlayerEvent::Aid(_))));
    assert!(has(
        |e| matches!(e, PlayerEvent::Chapters(c) if c.len() == 3)
    ));
    assert!(has(|e| matches!(e, PlayerEvent::Seeking(_))));
    assert!(has(|e| matches!(e, PlayerEvent::VideoSize(1280, 720))));
    // ARC-004 end to end: at most ~30 time-pos events per second
    let n = seen
        .iter()
        .filter(|e| matches!(e, PlayerEvent::TimePos(_)))
        .count();
    assert!(n <= 3 * 31, "{n} time-pos events in 3 s");
}

// T-PLY-001
#[test]
#[ignore = "L5: needs libmpv and `cargo xtask fixtures`"]
fn commands_seek_speed_volume_and_frame_step() {
    let mut t = Harness::new();
    t.load("av_basic.mkv", LoadRequest::default());
    t.loaded();
    t.h.set_pause(true).unwrap();
    t.h.seek_absolute(5.0).unwrap();
    t.until("time-pos", |v| {
        v.parse::<f64>().is_ok_and(|p| (p - 5.0).abs() < 0.1)
    });
    assert!((t.time_pos() - 5.0).abs() < 0.1, "{}", t.time_pos());
    t.h.seek_relative(3.0).unwrap();
    t.until("time-pos", |v| {
        v.parse::<f64>().is_ok_and(|p| (p - 8.0).abs() < 0.1)
    });
    assert!((t.time_pos() - 8.0).abs() < 0.1, "{}", t.time_pos());
    t.h.seek_relative(-3.0).unwrap();
    t.until("time-pos", |v| {
        v.parse::<f64>().is_ok_and(|p| (p - 5.0).abs() < 0.1)
    });
    assert!((t.time_pos() - 5.0).abs() < 0.1, "{}", t.time_pos());
    t.h.set_speed(10.0).unwrap();
    assert_eq!(t.until("speed", |v| v.starts_with("4.0")), "4.000000");
    t.h.set_speed(0.1).unwrap();
    assert_eq!(t.until("speed", |v| v.starts_with("0.25")), "0.250000");
    t.h.set_volume(200.0).unwrap();
    assert_eq!(t.until("volume", |v| v.starts_with("150")), "150.000000");
    t.h.toggle_pause().unwrap();
    assert_eq!(t.until("pause", |v| v == "no"), "no");

    let mut t = Harness::new();
    t.load("av_vfr.mkv", LoadRequest::default());
    t.loaded();
    // let the first frames come out, then step from a settled, paused position
    t.until("time-pos", |v| v.parse::<f64>().is_ok_and(|p| p >= 0.3));
    t.h.set_pause(true).unwrap();
    t.until("pause", |v| v == "yes");
    std::thread::sleep(Duration::from_millis(200));
    let before = t.time_pos();
    t.h.frame_step(true).unwrap();
    let after = t.until("time-pos", |v| v.parse::<f64>().is_ok_and(|p| p > before));
    assert!(
        after.parse::<f64>().unwrap() > before,
        "{before} -> {after}"
    );
}

// T-PLY-003
#[test]
#[ignore = "L5: needs libmpv and `cargo xtask fixtures`"]
fn audio_tracks_are_listed_and_selectable() {
    let mut t = Harness::new();
    t.load("av_basic.mkv", LoadRequest::default());
    let seen = t.wait(
        Duration::from_secs(10),
        |e| matches!(e, PlayerEvent::Tracks(v) if !v.is_empty()),
    );
    let Some(PlayerEvent::Tracks(tracks)) = seen.last() else {
        panic!("{seen:?}")
    };
    let audio: Vec<_> = tracks.iter().filter(|t| t.kind == "audio").collect();
    assert_eq!(audio.len(), 2, "{tracks:?}");
    assert_eq!(audio[0].lang.as_deref(), Some("jpn"));
    assert_eq!(audio[1].lang.as_deref(), Some("eng"));
    t.h.set_aid(Some(audio[1].id)).unwrap();
    let id = audio[1].id;
    let seen = t.wait(Duration::from_secs(5), |e| *e == PlayerEvent::Aid(Some(id)));
    assert_eq!(seen.last(), Some(&PlayerEvent::Aid(Some(id))));
}

// T-PLY-005
#[test]
#[ignore = "L5: needs libmpv and `cargo xtask fixtures`"]
fn fixed_options_are_set() {
    let t = Harness::new();
    for (k, v) in FIXED {
        if k == "vo" {
            continue; // the tests use vo=null
        }
        assert_eq!(t.prop(&format!("options/{k}")), v, "{k}");
    }
}

// T-PLY-007
#[test]
#[ignore = "L5: needs libmpv and `cargo xtask fixtures`"]
fn resume_with_start_then_reset() {
    let mut t = Harness::new();
    t.load(
        "av_long.mkv",
        LoadRequest {
            start: Some(5.0),
            ..LoadRequest::default()
        },
    );
    t.loaded();
    t.h.set_pause(true).unwrap();
    let p = t.until("time-pos", |v| v.parse::<f64>().is_ok_and(|p| p >= 4.9));
    let p: f64 = p.parse().unwrap();
    assert!((4.9..=5.5).contains(&p), "{p}");
    assert_eq!(t.prop("start"), "none");
}

// T-PLY-008
#[test]
#[ignore = "L5: needs libmpv and `cargo xtask fixtures`"]
fn after_load_text_subtitles_are_off() {
    let mut t = Harness::new();
    t.load(
        "av_basic.mkv",
        LoadRequest {
            volume: Some(80.0),
            speed: Some(1.5),
            ..LoadRequest::default()
        },
    );
    t.loaded();
    assert_eq!(t.prop("sid"), "no");
    assert_eq!(t.prop("sub-visibility"), "no");
    assert!(t.prop("volume").starts_with("80"));
    assert!(t.prop("speed").starts_with("1.5"));
}

// T-PLY-009, T-PLY-010
#[test]
#[ignore = "L5: needs libmpv and `cargo xtask fixtures`"]
fn the_core_is_reused_and_speed_never_adds_scaletempo() {
    let mut t = Harness::new();
    // A mark stored in the core: a new core would not have it. (The global
    // counter alone is not enough, because the tests run in parallel.)
    t.h.set_user_data("instance", "first").unwrap();
    assert!(instances_created() >= 1);
    t.load("av_basic.mkv", LoadRequest::default());
    t.loaded();
    t.load("av_vfr.mkv", LoadRequest::default());
    t.loaded();
    assert_eq!(
        t.prop("user-data/nikomiru/instance").trim_matches('"'),
        "first",
        "the core was recreated"
    );
    t.h.set_speed(1.5).unwrap();
    t.until("speed", |v| v.starts_with("1.5"));
    assert!(
        !t.prop("af").contains("scaletempo"),
        "af = {}",
        t.prop("af")
    );
}

// T-PLY-012
#[test]
#[ignore = "L5: needs libmpv and `cargo xtask fixtures`"]
fn errors_are_reported_and_the_player_stays_usable() {
    let mut t = Harness::new();
    let missing = fixture("av_basic.mkv").replace("av_basic", "does_not_exist");
    let (token, _) = t.h.load(&missing, LoadRequest::default()).unwrap();
    t.token = token;
    let seen = t.wait(Duration::from_secs(10), |e| {
        matches!(e, PlayerEvent::EndFile(_))
    });
    assert!(
        matches!(seen.last(), Some(PlayerEvent::EndFile(EndFile::Error(_)))),
        "{seen:?}"
    );

    t.load("corrupt_header.mkv", LoadRequest::default());
    let seen = t.wait(Duration::from_secs(10), |e| {
        matches!(e, PlayerEvent::EndFile(_) | PlayerEvent::FileLoaded)
    });
    assert!(!seen.is_empty(), "no event for a corrupt file");

    t.load("av_basic.mkv", LoadRequest::default());
    t.loaded();
}
